client_script:
frappe.web_form.after_load = function(){
  var user = (frappe.session && frappe.session.user) ? frappe.session.user : null;
  if (!user || user === 'Guest') return;

  function _restruct(){ setTimeout(function(){ if (window.kyaRestructureForm) window.kyaRestructureForm(); }, 200); }

  function boot(roles){
    roles = roles || [];
    var isCaissier = roles.indexOf('Caissier') !== -1;
    var isComptable = roles.indexOf('Comptable') !== -1;
    var isDFC = roles.indexOf('DFC') !== -1;
    var isAdmin = roles.indexOf('Accounts Manager') !== -1 || roles.indexOf('System Manager') !== -1;
    // Le comptable / l'admin peut saisir POUR un caissier : champ cherchable, non verrouille.
    var peutChoisir = isComptable || isAdmin;

    function _apply_signature_visibility() {
      var state = frappe.web_form.doc.workflow_state || 'Brouillon';
      var caissier_edit = isAdmin || ((isCaissier || isComptable) && (state === 'Brouillon' || state === 'Rejeté'));
      frappe.web_form.set_df_property('signature_caissiere', 'read_only', caissier_edit ? 0 : 1);
      var comptable_edit = isAdmin || (isComptable && state === 'En attente Comptable');
      frappe.web_form.set_df_property('signature_comptable', 'read_only', comptable_edit ? 0 : 1);
      frappe.web_form.set_df_property('signataire_comptable', 'hidden', 0);
      frappe.web_form.set_df_property('date_signature_comptable', 'hidden', 0);
      var dfc_edit = isAdmin || (isDFC && state === 'En attente DFC');
      frappe.web_form.set_df_property('signature_dfc', 'read_only', dfc_edit ? 0 : 1);
      frappe.web_form.set_df_property('signataire_dfc', 'hidden', 0);
      frappe.web_form.set_df_property('date_signature_dfc', 'hidden', 0);
      if (isComptable && state === 'En attente Comptable' && !frappe.web_form.doc.signataire_comptable) {
        frappe.db.get_value('Employee', {user_id: user, status: 'Active'}, ['employee_name']).then(function(res){
          if (res && res.message && res.message.employee_name) {
            frappe.web_form.set_value('signataire_comptable', res.message.employee_name);
            frappe.web_form.set_value('date_signature_comptable', frappe.datetime.get_today());
          }
        });
      }
      if (isDFC && state === 'En attente DFC' && !frappe.web_form.doc.signataire_dfc) {
        frappe.db.get_value('Employee', {user_id: user, status: 'Active'}, ['employee_name']).then(function(res){
          if (res && res.message && res.message.employee_name) {
            frappe.web_form.set_value('signataire_dfc', res.message.employee_name);
            frappe.web_form.set_value('date_signature_dfc', frappe.datetime.get_today());
          }
        });
      }
    }

    function _fill(emp){
      if (emp && emp.name){
        frappe.web_form.set_value('caissiere', emp.name);
        if (emp.employee_name) frappe.web_form.set_value('caissiere_name', emp.employee_name);
      }
    }

    // ---- Champ Caissier : ID Employe attendu, jamais un nom libre ----
    if (peutChoisir) {
      // Comptable/Admin : cherche le caissier par son nom et le selectionne.
      frappe.web_form.set_df_property('caissiere', 'read_only', 0);
      frappe.web_form.set_df_property('caissiere', 'description',
        'Tapez le nom du caissier et sélectionnez-le dans la liste.');
      _apply_signature_visibility(); _restruct();
    } else if (frappe.web_form.doc.caissiere) {
      _apply_signature_visibility(); _restruct();
    } else {
      // Caissier : auto-remplissage par le compte connecte ; sinon recherche par nom.
      frappe.db.get_value('Employee', {user_id: user, status: 'Active'}, ['name','employee_name']).then(function(r1){
        var e1 = (r1 && r1.message) ? r1.message : null;
        if (e1 && e1.name) {
          _fill(e1);
          frappe.web_form.set_df_property('caissiere', 'read_only', 1);
        } else {
          // "J'ai oublie mon ID RH" : le champ reste cherchable par nom.
          frappe.web_form.set_df_property('caissiere', 'read_only', 0);
          frappe.web_form.set_df_property('caissiere', 'description',
            "Vous ne connaissez pas votre ID RH ? Tapez votre nom et sélectionnez-le dans la liste.");
        }
        _apply_signature_visibility(); _restruct();
      });
    }

    function recompute() {
      var rows = (frappe.web_form.doc.lignes || []);
      var solde = parseFloat(frappe.web_form.doc.solde_precedent || 0);
      var te = 0, ts = 0;
      rows.forEach(function(row){
        var e = parseFloat(row.entree || 0);
        var s = parseFloat(row.sortie || 0);
        te += e; ts += s; solde += e - s; row.solde = solde;
      });
      frappe.web_form.set_value('total_entrees', te);
      frappe.web_form.set_value('total_sorties', ts);
      frappe.web_form.set_value('solde_final', parseFloat(frappe.web_form.doc.solde_precedent || 0) + te - ts);
    }

    frappe.web_form.after_save = function() { recompute(); _apply_signature_visibility(); };
    recompute();

    // Garde-fou : refuse une soumission sans caissier selectionne (evite l'erreur cryptique).
    frappe.web_form.validate = function(){
      if (!frappe.web_form.doc.caissiere) {
        frappe.msgprint({title: 'Caissier requis',
          message: 'Veuillez sélectionner le caissier (tapez le nom et choisissez-le dans la liste).',
          indicator: 'red'});
        return false;
      }
      return true;
    };
  }

  // Roles fiables meme sur le portail (frappe.boot est vide cote portail).
  if (window._kyaCtx && window._kyaCtx.roles) {
    boot(window._kyaCtx.roles);
  } else {
    frappe.call({
      method: 'kya_hr.api.get_session_context',
      callback: function(r){ window._kyaCtx = (r && r.message) || {roles: []}; boot(window._kyaCtx.roles || []); },
      error: function(){ boot((frappe.boot && frappe.boot.user && frappe.boot.user.roles) || []); }
    });
  }
};
